public class ScoreTracker {
    public static void main(String[] args) {
        int score = 0;

        score += 10;   System.out.println(score);   // 10
        score += 25;   System.out.println(score);   // 35
        score -= 5;    System.out.println(score);   // 30
        score *= 2;    System.out.println(score);   // 60
        score /= 4;    System.out.println(score);   // 15
        score++;       System.out.println(score);   // 16
        score--;       System.out.println(score);   // 15
    }
}
